public static int countOilDeposits(char[][] grid) {

    // Calculate the number of columns in the grid
    int nCols = grid[0].length;

    // Initialize a 2D array to keep track of visited cells
    boolean[][] visited = new boolean[grid.length][nCols];

    // Initialize the number of distinct oil deposits to 0
    int numOilDeposits = 0;

    // Iterate over each row in the grid
    for (int i = 0; i < grid.length; i++) {
      // Iterate over each column in the grid
      for (int j = 0; j < nCols; j++) {
        // If the current cell is an oil deposit and we haven't visited it before,
        // increment the number of oil deposits and mark the cell as visited
        if (grid[i][j] == '@' && !visited[i][j]) {
          numOilDeposits++;
          visited[i][j] = true;

          // Recursively search all connected oil deposits
          countOilDeposits(grid, i, j, visited);
        }
      }
    }

    return numOilDeposits;
  }

private static void countOilDeposits(char[][] grid, int row, int col, boolean[][] visited) {

    // If the current cell is an oil deposit and we haven't visited it before,
    // mark the cell as visited and increment the number of oil deposits
    if (grid[row][col] == '@' && !visited[row][col]) {
      visited[row][col] = true;
    }

    // Check if the cell is on the edge of the grid,
    // return if we are at the edge
    if (row == 0 || row == grid.length - 1 || col == 0 || col == grid[0].length - 1) return;

    // Check if the cell to the left is an oil deposit and has not been visited
    if (grid[row][col - 1] == '@' && !visited[row][col - 1]) {
      countOilDeposits(grid, row, col - 1, visited);
    }

    // Check if the cell to the right is an oil deposit and has not been visited
    if (grid[row][col + 1] == '@' && !visited[row][col + 1]) {
      countOilDeposits(grid, row, col + 1, visited);
    }

    // Check if the cell above is an oil deposit and has not been visited
    if (grid[row - 1][col] == '@' && !visited[row - 1][col]) {
      countOilDeposits(grid, row - 1, col, visited);
    }

    // Check if the cell below is an oil deposit and has not been visited
    if (grid[row + 1][col] == '@' && !visited[row + 1][col]) {
      countOilDeposits(grid, row + 1, col, visited);
    }
  }

