public int minInsertions(String s) {
    int minInsertions = 0;
    Stack<Character> stack = new Stack<>();

    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
        } else {
            stack.pop();
            if (stack.isEmpty()) {
                minInsertions++;
                stack.push(c);
            }
        }
    }

    while (!stack.isEmpty()) {
        minInsertions++;
        stack.pop();
    }

    return minInsertions;
}

