        char nextChar = charArray[i + 1];
        if (currentChar == Character.toLowerCase(nextChar)) {
            shouldRepeat = true;
            charArray[i + 1] = '\0';
        } else if (currentChar == Character.toUpperCase(nextChar)) {
            shouldRepeat = true;
            charArray[i] = '\0';
