    int rows = mat.length, cols = mat[0].length;
    int[] result = new int[rows * cols];
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            int index = i + j;
            result[index] = mat[i][j];
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    int smallest = -1;
    int[] digits = new int[10];
    for (int i = 1; i <= 9; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    digits[0] = n;
    Arrays.sort(digits);
    int permutation = 0;
    for (int i = 0; i < 10; i++) {
        permutation *= 10;
        permutation += digits[i];
    }
    if (permutation > smallest) {
        smallest = permutation;
    }
    return smallest;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<String>();

    for (int i = 0; i <= n / 2; i++) {
        String num = "";
        for (int j = 0; j < n / 2; j++) {
            num += "9";
        }
        num += (n % 2 == 0) ? "1" : "9";
        for (int j = n / 2 - 1; j >= 0; j--) {
            num += "9";
        }
        result.add(num);
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    return points.length == 3 && points[0][0] == points[1][1] && points[1][0] == points[2][1] && points[2][0] == points[0][1];
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int index2 = 0, index3 = 0, index5 = 0;
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[index2] * 2, Math.min(uglyNumbers[index3] * 3, uglyNumbers[index5] * 5));
        uglyNumbers[i] = min;
        if (min == uglyNumbers[index2] * 2) index2++;
        if (min == uglyNumbers[index3] * 3) index3++;
        if (min == uglyNumbers[index5] * 5) index5++;
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int longestSubstringLength = 0;
    int currentLength = 0;
    char currentChar = '\0';
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            currentLength++;
        } else {
            currentLength = 1;
            currentChar = c;
        }
        if (currentLength > longestSubstringLength) {
            longestSubstringLength = currentLength;
        }
    }
    return longestSubstringLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] != nums[i - 1]) {
            sum += nums[i];
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    // initialize variables
    int sum = 0;
    int count = 0;
    int currentSquare = 1;

    // loop until the sum is greater than or equal to the target number
    while (sum < n) {
        // calculate the next perfect square
        currentSquare = currentSquare * currentSquare;

        // increment the count if the current square is less than or equal to the target number
        if (currentSquare <= n) {
            count++;
        }

        // add the current square to the sum
        sum += currentSquare;
    }

    // return the count of minimal perfect squares
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversed = new StringBuilder();
    for (String word : words) {
        reversed.append(reverse(word));
        reversed.append(" ");
    }
    return reversed.toString().trim();
}
